Thank you so much for the help so far by the way
EDIT: I managed to make it work with the help of a friend! I had to force the TextEx within HUDMaker to evaluate by adding this to the .js itself:
Sprite_HUDTextEx.prototype.convertEscapeCharacters = function(text) {
text = text.replace(/\${(.*?)}/g, (match, p1) => {
try {
return eval(p1); // Evaluate JavaScript within ${...}
} catch (e) {
console.error("Error evaluating expression:", e);
return "";
}
});
return Window_Base.prototype.convertEscapeCharacters.call(this, text);
};
It's been a real nightmare to crack this one but it finally works! Ty everyone for the help too
